// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        uint beforeContractBal = address(c).balance;
        uint256 beforeRecorded;
        try c.getBalance(address(this)) returns (uint256 __r) { beforeRecorded = __r; } catch { return; }
        try c.addToBalance{value: depositAmount}() {} catch { return; }
        uint afterContractBal = address(c).balance;
        uint256 afterRecorded;
        try c.getBalance(address(this)) returns (uint256 __r) { afterRecorded = __r; } catch { return; }
        vm.assume(afterContractBal >= beforeContractBal);
        vm.assume(afterRecorded >= beforeRecorded);
        bool withdrew;
        try c.withdrawBalance() {
            withdrew = true;
        } catch {
            withdrew = false;
        }
        uint finalContractBal = address(c).balance;
        uint256 finalRecorded;
        try c.getBalance(address(this)) returns (uint256 __r) { finalRecorded = __r; } catch { return; }
        assertTrue((withdrew && finalRecorded == 0 && (beforeRecorded + depositAmount) >= (afterContractBal - finalContractBal))
                || (!withdrew && finalRecorded == afterRecorded));
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable { }
}
